// Control flow
void testControlFlow() {
    // If-else
    int x = 10;
    if (x > 5) {
        std::cout << "x > 5" << std::endl;
    } else if (x < 5) {
        std::cout << "x < 5" << std::endl;
    } else {
        std::cout << "x == 5" << std::endl;
    }
    
    // For loop
    std::cout << "For loop: ";
    for (int i = 0; i < 5; i++) {
        std::cout << "i: " << i << " ";
    }
    std::cout << std::endl;
    
    // While-like for loop
    int j = 0;
    std::cout << "While-like loop: ";
    while (j < 3) {
        std::cout << "j: " << j << " ";
        j++;
    }
    std::cout << std::endl;
    
    // Infinite loop with break
    int k = 0;
    std::cout << "Infinite loop with break: ";
    while (true) {
        if (k >= 3) {
            break;
        }
        std::cout << "k: " << k << " ";
        k++;
    }
    std::cout << std::endl;
}

// Switch statement
void testSwitch() {
    std::string day = "Monday";
    
    if (day == "Monday") {
        std::cout << "It's Monday" << std::endl;
    } else if (day == "Tuesday") {
        std::cout << "It's Tuesday" << std::endl;
    } else {
        std::cout << "It's another day" << std::endl;
    }
    
    // Switch with no condition
    int hour = 14;
    if (hour < 12) {
        std::cout << "Good morning" << std::endl;
    } else if (hour < 18) {
        std::cout << "Good afternoon" << std::endl;
    } else {
        std::cout << "Good evening" << std::endl;
    }
}

