// Error handling
std::pair<int, bool> divide(int a, int b) {
    if (b == 0) {
        return std::make_pair(0, false); // false indicates error
    }
    return std::make_pair(a / b, true); // true indicates success
}

void testErrorHandling() {
    auto result1 = divide(10, 2);
    if (!result1.second) {
        std::cout << "Error: division by zero" << std::endl;
    } else {
        std::cout << "Result: " << result1.first << std::endl;
    }
    
    auto result2 = divide(10, 0);
    if (!result2.second) {
        std::cout << "Error: division by zero" << std::endl;
    } else {
        std::cout << "Result: " << result2.first << std::endl;
    }
}

// Concurrency (basic test)
template<typename T>
struct Channel {
    std::queue<T> data_queue;
    std::mutex mutex;
    std::condition_variable cv;
    
    Channel() {}
    
    void send(T value) {
        std::lock_guard<std::mutex> lock(this->mutex);
        this->data_queue.push(value);
        this->cv.notify_one();
    }
    
    T receive() {
        std::unique_lock<std::mutex> lock(this->mutex);
        this->cv.wait(lock);
        T result = this->data_queue.front();
        this->data_queue.pop();
        return result;
    }
};

void testConcurrency() {
    Channel<int> ch;
    
    std::thread t([&ch]() {
        ch.send(42);
    });
    
    int value = ch.receive();
    std::cout << "Received from channel: " << value << std::endl;
    
    t.join();
    
    // Buffered channel simulation
    std::vector<int> ch2;
    ch2.push_back(1);
    ch2.push_back(2);
    
    int val1 = ch2[0];
    int val2 = ch2[1];
    ch2.erase(ch2.begin());
    ch2.erase(ch2.begin());
    
    std::cout << "Buffered channel: " << val1 << ", " << val2 << std::endl;
}

