// Generics test
template<typename T>
T Min(T a, T b) {
    if (a < b) {
        return a;
    }
    return b;
}

template<typename T, typename U>
std::vector<U> Map(std::vector<T> slice, std::function<U(T)> f) {
    std::vector<U> result(slice.size());
    for (size_t i = 0; i < slice.size(); i++) {
        result[i] = f(slice[i]);
    }
    return result;
}

template<typename T>
T Add(T a, T b) {
    return a + b;
}

void testGenerics() {
    // Test generics
    std::cout << "Min int: " << Min(5, 3) << std::endl;
    std::cout << "Min string: " << Min(std::string("apple"), std::string("banana")) << std::endl;
    std::cout << "Add int: " << Add(5, 3) << std::endl;
    std::cout << "Add double: " << Add(5.5, 3.3) << std::endl;
    
    std::vector<int> numbers = {1, 2, 3, 4, 5};
    auto doubled = Map<int, int>(numbers, [](int x) { return x * 2; });
    std::cout << "Mapped: [";
    for (size_t i = 0; i < doubled.size(); i++) {
        if (i > 0) std::cout << ", ";
        std::cout << doubled[i];
    }
    std::cout << "]" << std::endl;
}

