// Function types and closures
int add_func(int a, int b) {
    return a + b;
}

int multiply_func(int a, int b) {
    return a * b;
}

void testFunctionTypes() {
    // Function pointer
    int (*math_func)(int, int);
    
    math_func = add_func;
    int add_result = math_func(5, 3);
    
    math_func = multiply_func;
    int multiply_result = math_func(5, 3);
    
    std::cout << "Add: " << add_result << ", Multiply: " << multiply_result << std::endl;
    
    // Closure simulation
    static int count = 0;
    auto counter = []() -> int {
        return ++count;
    };
    
    std::cout << "Counter: " << counter() << ", " << counter() << ", " << counter() << std::endl;
}

